103: *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
104: [hidden]{display:none!important}
105: html,body{margin:0;padding:0;height:100%;overflow:hidden;background:#9ed7e5;color:var(--ink);font-family:"KotaBody","Trebuchet MS","Segoe UI",system-ui,sans-serif}
106: button,input{font:inherit;color:inherit}
107: button{cursor:pointer;border:0;background:none}
108: button:focus-visible,input:focus-visible{outline:3px solid #ffcf5f;outline-offset:2px}
109: #app{position:fixed;inset:0}
110: #scene{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;cursor:grab}
111: #scene.dragging{cursor:grabbing}
112: #scene.building{cursor:crosshair}
