114: .ic{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;flex:none}
115: #hud{position:absolute;inset:0;pointer-events:none;z-index:5}
116: #hud>*{pointer-events:auto}
