118: /* ---------- top bar ---------- */
119: #topbar{
120:   position:absolute;top:calc(10px + var(--safe-top));left:12px;right:12px;height:66px;
121:   display:flex;align-items:center;gap:14px;padding:0 12px 0 14px;border-radius:20px;
122:   background:linear-gradient(120deg,rgba(6,52,57,.96),rgba(9,86,80,.94));
123:   border:1px solid rgba(255,255,255,.13);
124:   box-shadow:0 12px 34px rgba(2,32,38,.3),inset 0 1px 0 rgba(255,255,255,.14);
125:   color:#f7fffd;backdrop-filter:blur(10px);z-index:20;
126: }
127: .brand{display:flex;align-items:center;gap:11px;min-width:190px}
128: .brand-mark{width:42px;height:42px;border-radius:13px;background:linear-gradient(150deg,#ffd76a,#ffb020);color:#5a3600;display:grid;grid-template-columns:1fr 1fr;align-items:center;justify-items:center;font-family:"KotaDisplay",sans-serif;font-weight:900;font-size:17px;letter-spacing:-.08em;box-shadow:inset 0 2px 0 rgba(255,255,255,.55),0 4px 10px rgba(0,0,0,.22);padding:0 4px;transform:rotate(-3deg)}
129: .brand-mark span:first-child{transform:translateY(-3px)}
130: .brand-mark span:last-child{transform:translateY(3px)}
131: .city-name{font-family:"KotaDisplay",sans-serif;font-weight:800;font-size:18px;letter-spacing:.01em;line-height:1.15;max-width:190px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
132: .city-sub{font-size:10.5px;letter-spacing:.04em;color:#a9d9d3;display:flex;gap:7px;align-items:center;margin-top:2px;white-space:nowrap}
133: .city-sub .dot{opacity:.5}
134: .stats{display:flex;align-items:center;gap:6px;flex:1;justify-content:center;flex-wrap:nowrap;overflow:hidden}
135: .stat{display:flex;align-items:center;gap:6px;height:40px;padding:0 10px;border-radius:11px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.08);font-weight:700;font-size:14px;white-space:nowrap}
136: .stat .ic{width:17px;height:17px;color:#9fded6}
137: .stat small{font-size:10px;color:#9fc8c3;font-weight:600;letter-spacing:.02em}
138: .stat.money .ic{color:var(--sun)}
139: .stat.money span{color:#ffe08a}
140: .stat.money small{color:#9fd0a4}
141: .stat.money small.neg{color:#ff9b86}
142: .stat:nth-child(3) .ic{color:#ffe28a}
143: .stat:nth-child(4) .ic{color:#ffd85e}
144: .stat:nth-child(5) .ic{color:#8fd8ff}
145: .top-actions{display:flex;gap:4px;margin-left:auto}
146: .icon-btn{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;color:inherit;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.09);transition:.15s}
147: .icon-btn:hover{background:rgba(255,255,255,.17);transform:translateY(-1px)}
148: .icon-btn:active{transform:translateY(0) scale(.96)}
149: .icon-btn.ghost{background:transparent;border-color:transparent;color:var(--ink-soft)}
150: .icon-btn.ghost:hover{background:rgba(9,57,62,.07)}
151: #topbar .icon-btn{color:#d9f4ef}
152: #topbar .icon-btn:hover{background:rgba(255,255,255,.18)}
153: 
154: /* ---------- rail ---------- */
155: #rail{
156:   position:absolute;left:14px;top:calc(88px + var(--safe-top));bottom:96px;width:70px;
157:   display:flex;flex-direction:column;gap:6px;padding:8px 7px;border-radius:20px;
158:   background:var(--panel-glass);border:1px solid var(--line);box-shadow:var(--shadow);
159:   backdrop-filter:blur(12px);z-index:12;overflow-y:auto;scrollbar-width:none;
160: }
161: #rail::-webkit-scrollbar{display:none}
162: .rail-btn{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;min-height:54px;border-radius:13px;color:var(--ink-soft);font-size:9.5px;font-weight:700;letter-spacing:.01em;transition:.15s;flex:none}
163: .rail-btn .ic{width:23px;height:23px}
164: .rail-btn:hover{background:rgba(14,124,114,.08);color:var(--teal)}
165: .rail-btn.active{background:linear-gradient(160deg,#139a8d,#0b6a62);color:#fff;box-shadow:0 6px 14px rgba(10,79,75,.28),inset 0 1px 0 rgba(255,255,255,.22)}
166: .rail-btn .badge{position:absolute;top:3px;right:4px;min-width:16px;height:16px;border-radius:9px;background:var(--coral);color:#fff;font-size:9px;display:grid;place-items:center;padding:0 4px;box-shadow:0 2px 5px rgba(0,0,0,.2)}
167: .rail-spacer{flex:1;min-height:8px}
168: .rail-sep{height:1px;background:var(--line);margin:2px 5px}
169: .rail-btn.danger.active{background:linear-gradient(160deg,#ef6a4c,#c94a30);box-shadow:0 6px 14px rgba(160,50,30,.3)}
170: 
171: /* ---------- catalog ---------- */
172: .panel{background:var(--panel-glass);border:1px solid var(--line);box-shadow:var(--shadow);backdrop-filter:blur(14px)}
173: #catalog{
174:   position:absolute;left:96px;top:calc(88px + var(--safe-top));width:342px;max-height:calc(100% - 206px);
175:   border-radius:20px;display:flex;flex-direction:column;z-index:11;overflow:hidden;
176:   transition:opacity .2s,transform .24s cubic-bezier(.2,.9,.3,1);
177: }
178: #catalog.hidden{opacity:0;transform:translateX(-14px) scale(.98);pointer-events:none}
179: .catalog-head{display:flex;align-items:flex-start;justify-content:space-between;padding:16px 16px 0}
180: .eyebrow{font-size:9px;font-weight:800;letter-spacing:.16em;color:var(--teal-2);margin-bottom:3px}
181: .catalog-head h2,.side-head h2{margin:0;font-family:"KotaDisplay",sans-serif;font-size:20px;font-weight:800;letter-spacing:-.01em}
182: .catalog-blurb{margin:5px 16px 12px;font-size:11.5px;line-height:1.45;color:var(--ink-soft)}
183: .catalog-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:0 12px 12px;overflow-y:auto;overscroll-behavior:contain}
184: .catalog-grid::-webkit-scrollbar{width:5px}
185: .catalog-grid::-webkit-scrollbar-thumb{background:rgba(9,57,62,.18);border-radius:3px}
186: .card{
187:   position:relative;display:flex;flex-direction:column;border-radius:13px;border:1.5px solid var(--line);
188:   background:linear-gradient(180deg,#fff,#f7fbf8);overflow:hidden;text-align:left;transition:.15s;min-height:118px;
189: }
190: .card:hover{border-color:rgba(14,124,114,.45);transform:translateY(-2px);box-shadow:0 8px 18px rgba(9,57,62,.1)}
191: .card.active{border-color:var(--teal);box-shadow:0 0 0 2px rgba(14,124,114,.16),0 8px 18px rgba(9,57,62,.12)}
192: .card.locked{opacity:.62;filter:saturate(.6)}
193: .card.cant{opacity:.75}
194: .card-preview{position:relative;aspect-ratio:220/150;background:radial-gradient(circle at 50% 40%,#eafaf3,#d8efe6);border-bottom:1px solid rgba(9,57,62,.06);overflow:hidden}
195: .card-preview canvas{position:absolute;inset:0;width:100%;height:100%;display:block}
196: .card-body{padding:7px 8px 8px;display:flex;flex-direction:column;gap:2px;flex:1}
197: .card-name{font-size:11.5px;font-weight:800;line-height:1.22;color:var(--ink)}
198: .card-meta{display:flex;align-items:center;justify-content:space-between;margin-top:auto;padding-top:3px}
199: .card-cost{font-size:11px;font-weight:800;color:var(--teal-dark);display:flex;align-items:center;gap:2px}
200: .card-cost .ic{width:12px;height:12px}
201: .card-tag{font-size:8.5px;font-weight:800;letter-spacing:.04em;padding:2px 5px;border-radius:5px;background:rgba(14,124,114,.1);color:var(--teal)}
202: .card-lock{position:absolute;inset:0;display:flex;align-items:flex-end;justify-content:center;padding-bottom:34px;background:linear-gradient(180deg,transparent 35%,rgba(8,45,49,.06));pointer-events:none}
203: .lock-pill{display:flex;align-items:center;gap:4px;padding:4px 8px;border-radius:20px;background:rgba(7,47,51,.82);color:#fff;font-size:9px;font-weight:700;box-shadow:0 3px 8px rgba(0,0,0,.2)}
204: .lock-pill .ic{width:11px;height:11px}
205: .card .hurry{position:absolute;top:5px;left:5px;background:rgba(255,198,74,.95);color:#5a3a00;font-size:8px;font-weight:900;padding:3px 6px;border-radius:5px;letter-spacing:.04em}
206: .catalog-foot{padding:9px 14px;border-top:1px solid var(--line);font-size:10px;color:var(--ink-faint);display:flex;align-items:center;min-height:36px}
207: .catalog-foot b{color:var(--teal-dark)}
208: 
209: /* ---------- side panel ---------- */
210: #sidePanel{
211:   position:absolute;right:14px;top:calc(88px + var(--safe-top));bottom:96px;width:302px;border-radius:20px;z-index:11;overflow:hidden;
212:   transition:opacity .2s,transform .24s cubic-bezier(.2,.9,.3,1);
213: }
214: #sidePanel.hidden{opacity:0;transform:translateX(16px);pointer-events:none}
215: .side-scroll{height:100%;overflow-y:auto;padding:16px 15px 14px;overscroll-behavior:contain}
216: .side-scroll::-webkit-scrollbar{width:5px}
217: .side-scroll::-webkit-scrollbar-thumb{background:rgba(9,57,62,.16);border-radius:3px}
218: .side-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px}
219: .side-close{width:30px;height:30px}
220: .mini-wrap{position:relative;border-radius:13px;overflow:hidden;border:1px solid var(--line);background:#8ed3e2;height:144px}
221: #minimap{width:100%;height:100%;display:block;cursor:pointer}
222: .mini-badge{position:absolute;right:7px;bottom:6px;background:rgba(7,47,51,.75);color:#d8f4ef;font-size:8px;font-weight:700;letter-spacing:.05em;padding:3px 6px;border-radius:5px;pointer-events:none}
223: .expand-city-wrap{padding:9px 0 2px}
224: .expand-city-wrap .soft-btn{justify-content:space-between;padding:0 12px}
225: .expand-city-wrap .soft-btn span{font-size:10px}
226: .expand-city-wrap .soft-btn:disabled{opacity:.52;cursor:not-allowed;filter:grayscale(.25)}
227: .expand-city-wrap small{display:block;padding:5px 2px 0;color:var(--ink-faint);font-size:9px}
228: .side-section{padding:12px 0;border-bottom:1px solid var(--line)}
229: .section-label{font-size:9.5px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--ink-faint)}
230: .row-between{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:11.5px}
231: .row-between strong{font-size:15px;font-weight:800;color:var(--teal-dark)}
232: .row-between.small{color:var(--ink-soft);font-size:10.5px;padding-top:6px}
233: .row-between.small span:last-child{font-weight:700;color:var(--ink)}
234: .meter{height:8px;border-radius:5px;background:rgba(9,57,62,.09);overflow:hidden;margin:7px 0 9px}
235: .meter.slim{height:5px;margin:0;flex:1}
236: .meter-fill{height:100%;border-radius:5px;transition:width .5s cubic-bezier(.2,.9,.3,1);background:linear-gradient(90deg,#2ec27e,#7ee2a8)}
237: .meter-fill.happy{background:linear-gradient(90deg,#ffb020,#ffd971)}
238: .meter-fill.r{background:linear-gradient(90deg,#3aa96b,#78d79a)}
239: .meter-fill.c{background:linear-gradient(90deg,#3b8fd4,#78c2f2)}
