160:       ctx.globalAlpha = .18 + shimmer * .18;
161:       line(ctx, { x: T.x + 16, y: T.y + 10 }, { x: T.x + 25, y: T.y + 14.5 }, '#e9ffff', 1.4);
162:       line(ctx, { x: T.x + 9, y: T.y + 20 }, { x: T.x + 17, y: T.y + 24 }, '#d8fbff', 1.2);
163:       line(ctx, { x: T.x + 27, y: T.y + 21 }, { x: T.x + 35, y: T.y + 25 }, '#d8fbff', 1.1);
