170:         if (dir === 'e') line(ctx, R, B, 'rgba(240,255,255,.55)', 2);
171:         if (dir === 's') line(ctx, B, L, 'rgba(240,255,255,.55)', 1.8);
172:         if (dir === 'w') line(ctx, L, T, 'rgba(240,255,255,.6)', 2);
173:       };
174:       foam('n'); foam('e'); foam('s'); foam('w');
175:       return;
176:     }
177:     let base;
178:     if (tile.terrain === 'sand') base = SAND[Math.floor(h * SAND.length)];
179:     else base = GRASS[Math.floor(h * GRASS.length)];
180:     poly(ctx, [T, R, B, L], base);
