190:         line(ctx, { x: gx + 1, y: gy }, { x: gx - 1.7, y: gy - 2.6 }, '#5a9648', .9);
191:         if (h > .75) {
192:           ctx.fillStyle = h > .9 ? '#f7d85e' : '#f2fdf8';
193:           ctx.beginPath(); ctx.arc(gx + 6, gy - 3, 1.15, 0, 7); ctx.fill();
194:         }
195:         ctx.globalAlpha = 1;
196:       }
