199:       ctx.fillStyle = '#b99f66';
200:       for (let i = 0; i < 2; i++) {
201:         const sx = T.x + 12 + hash(x + i, y + 1) * 30;
202:         const sy = T.y + 8 + hash(x + 2, y + i) * 12;
203:         ctx.beginPath(); ctx.arc(sx, sy, .9, 0, 7); ctx.fill();
204:       }
205:       ctx.globalAlpha = 1;
206:     }
207:   }
208:   function neighbor(world, x, y, dir) {
209:     const dx = dir === 'n' ? -1 : dir === 's' ? 1 : 0;
210:     const dy = dir === 'w' ? -1 : dir === 'e' ? 1 : 0;
211:     const nx = x + dx, ny = y + dy;
212:     if (nx < 0 || ny < 0 || nx >= world.gridSize || ny >= world.gridSize) return null;
213:     return world.grid[ny * world.gridSize + nx];
