239:     const mids = {
240:       n: { x: (T.x + L.x) / 2, y: (T.y + L.y) / 2 },
241:       e: { x: (R.x + B.x) / 2, y: (R.y + B.y) / 2 },
242:       s: { x: (B.x + L.x) / 2, y: (B.y + L.y) / 2 },
243:       w: { x: (T.x + L.x) / 2, y: (T.y + L.y) / 2 }
