245:     const dirs = [
246:       ['n', { x: (T.x + R.x) / 2, y: (T.y + R.y) / 2 }],
247:       ['e', { x: (R.x + B.x) / 2, y: (R.y + B.y) / 2 }],
248:       ['s', { x: (B.x + L.x) / 2, y: (B.y + L.y) / 2 }],
249:       ['w', { x: (T.x + L.x) / 2, y: (T.y + L.y) / 2 }]
250:     ];
251:     let connections = 0;
252:     for (const [dir, mid] of dirs) {
253:       if (neighbor(world, x, y, dir)?.road) {
254:         connections++;
255:         line(ctx, C, mid, 'rgba(247,239,209,.72)', 1.5, [5, 5]);
256:       }
