261:         const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
262:         line(ctx, { x: C.x + Math.cos(a) * 5, y: C.y + Math.sin(a) * 3 }, { x: C.x + Math.cos(a) * 8, y: C.y + Math.sin(a) * 5 }, '#fff', 1.6);
263:       }
264:       ctx.globalAlpha = 1;
265:     }
266:     // pebbles
267:     ctx.globalAlpha = .15;
268:     ctx.fillStyle = '#e8e2d2';
269:     for (let i = 0; i < 2; i++) {
270:       const px = T.x + 12 + hash(x + i, y) * 34, py = T.y + 12 + hash(x, y + i) * 14;
271:       ctx.beginPath(); ctx.arc(px, py, .8, 0, 7); ctx.fill();
272:     }
273:     ctx.globalAlpha = 1;
274:   }
