326:         const a = { x: lerp(L.x, B.x, t / 2), y: lerp(L.y, B.y, t / 2) };
327:         const b = { x: lerp(apex.x, B.x, t * .8), y: lerp(apex.y, B.y, t * .8) };
328:         line(ctx, { x: lerp(L.x, B.x, 1 - t), y: lerp(L.y, B.y, 1 - t) }, { x: lerp(apex.x, L.x, .5), y: lerp(apex.y, L.y, .5) }, shade(color, .5), .8);
