333:   function drawWindows(ctx, faceA, faceB, height, rows, cols, opt) {
334:     const o = opt || {};
335:     const top = o.top || 6, bottom = o.bottom || 7;
336:     const usable = height - top - bottom;
337:     if (usable < 6) return;
338:     const winH = Math.min(o.winH || 6, usable / rows * .5);
