341:     const frame = o.frame || 'rgba(255,255,255,.28)';
342:     const stepX = (faceB.x - faceA.x) / cols;
343:     const stepY = (faceB.y - faceA.y) / cols;
344:     for (let r = 0; r < rows; r++) {
345:       const wy = height - top - (usable / rows) * (r + .5);
346:       for (let c = 0; c < cols; c++) {
347:         const cx = faceA.x + stepX * (c + .5);
348:         const cy = faceA.y + stepY * (c + .5) - wy;
349:         const ex = (stepX / Math.abs(stepX || 1)) * winW;
350:         ctx.beginPath();
351:         ctx.moveTo(cx - ex / 2, cy);
352:         ctx.lineTo(cx + ex / 2, cy);
