472:     for (let y = 0; y < world.gridSize; y++) {
473:       for (let x = 0; x < world.gridSize; x++) {
474:         const t = world.grid[y * world.gridSize + x];
475:         if (!t) continue;
476:         const s = iso(x, y);
477:         if (s.x < left - 90 || s.x > right + 90 || s.y < top - 80 || s.y > bottom + 80) continue;
478:         drawTerrain(ctx, world, x, y, t, time);
479:         if (t.road) drawRoad(ctx, world, x, y, t);
480:       }
481:     }
482:     const objs = [];
483:     for (const b of world.buildings) {
484:       const s = iso(b.x, b.y);
485:       if (s.x < left - 260 || s.x > right + 260 || s.y < top - 120 || s.y > bottom + 260) continue;
486:       objs.push({ d: b.x + b.y + (b.w + b.h - 2) * .34, b });
487:     }
488:     if (world.cars) {
489:       for (const c of world.cars) {
490:         if (c.x < left / 32 - 20 || c.y < top / 16 - 20) { /* rough */ }
491:         objs.push({ d: c.x + c.y, car: c });
492:       }
493:     }
494:     objs.sort((a, b) => a.d - b.d);
495:     for (const o of objs) {
496:       if (o.b) drawObject(ctx, o.b, time);
497:       else drawCar(ctx, o.car, time);
498:     }
499:     if (opts.selected) {
500:       const b = opts.selected;
501:       const pts = diamondPoints(b.x, b.y, b.w, b.h, .02);
502:       ctx.save();
503:       ctx.setLineDash([6, 4]);
504:       poly(ctx, pts, 'rgba(255,255,255,.05)', 'rgba(255,255,255,.9)', 2.2);
505:       ctx.setLineDash([]);
506:       ctx.restore();
507:       if (DEFS[b.defId] && DEFS[b.defId].radius) drawZoneRadius(ctx, b, 'rgba(46,194,126,.55)');
508:     }
509:     if (opts.ghost) drawGhost(ctx, opts.ghost, time);
510:     // night overlay (screen space)
511:     if (NIGHT > .02) {
512:       ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
513:       ctx.fillStyle = `rgba(14,26,62,${NIGHT * .42})`;
514:       ctx.fillRect(0, 0, viewW, viewH);
515:       if (opts.dusk) {
516:         ctx.fillStyle = `rgba(255,127,58,${opts.dusk * .12})`;
517:         ctx.fillRect(0, 0, viewW, viewH);
518:       }
519:     }
520:   }
