556:     const pts = diamondPoints(x, y, def.w, def.h, .02);
557:     poly(ctx, pts, valid ? 'rgba(80,220,130,.16)' : 'rgba(255,90,60,.2)', valid ? '#4ee58a' : '#ff5b3d', 2);
