627:   function drawLot(ctx, b, def, color, letter, time) {
628:     const p = diamondPoints(b.x, b.y, 1, 1, .035);
629:     poly(ctx, p, color + '33');
630:     ctx.save();
631:     ctx.setLineDash([5, 4]);
632:     poly(ctx, diamondPoints(b.x, b.y, 1, 1, .11), null, color, 1.4);
633:     ctx.restore();
634:     // diagonal tint stripes
635:     ctx.save();
636:     ctx.beginPath(); poly(ctx, diamondPoints(b.x, b.y, 1, 1, .08), null); ctx.clip();
637:     ctx.globalAlpha = .1;
638:     for (let i = -1; i < 5; i++) {
639:       const t = i * .28;
640:       line(ctx, iso(b.x + t, b.y), iso(b.x + t + .5, b.y + 1), color, 2);
