645:     line(ctx, { x: sp.x, y: sp.y }, { x: sp.x, y: sp.y - 10 }, '#8b7355', 1.6);
646:     poly(ctx, [{ x: sp.x - 1, y: sp.y - 16 }, { x: sp.x + 10, y: sp.y - 12 }, { x: sp.x + 10, y: sp.y - 6 }, { x: sp.x - 1, y: sp.y - 10 }], '#fdf9ee', color, .8);
647:     ctx.fillStyle = color; ctx.font = '700 6px "Trebuchet MS",sans-serif'; ctx.textAlign = 'center';
648:     ctx.fillText(letter, sp.x + 4.5, sp.y - 9);
649:     // small props
650:     const a = iso(b.x + .25, b.y + .7);
651:     ctx.globalAlpha = .5; ctx.fillStyle = shade(color, .7);
652:     for (let i = 0; i < 3; i++) { ctx.beginPath(); ctx.arc(a.x + i * 3, a.y - i * 1.3, 1.2, 0, 7); ctx.fill(); }
