771:   function drawFactory(ctx, b, def, time) {
772:     const pal = addVariantColors(b, KK.FACTORY_PALETTES);
773:     const lv = b.level || 1;
774:     basePad(ctx, b, '#b9b2a2', '#c4bdac');
775:     const h = lv === 1 ? 22 : lv === 2 ? 32 : 42;
776:     const g = boxGeo(b.x, b.y, 1, 1, .1);
777:     drawBox(ctx, b.x, b.y, 1, 1, h, { inset: .1, wall: pal.wall, left: shade(pal.wall, .86), right: shade(pal.wall, .68), top: pal.roof });
778:     // sawtooth / vents
779:     ctx.globalAlpha = .3;
780:     for (let i = 0; i < 3; i++) {
781:       const t = .18 + i * .26;
782:       line(ctx, { x: lerp(g.L.x, g.B.x, t), y: lerp(g.L.y, g.B.y, t) - h }, { x: lerp(g.L.x, g.B.x, t) + 5, y: lerp(g.L.y, g.B.y, t) - h - 4 }, shade(pal.roof, .6), 1.2);
783:     }
784:     ctx.globalAlpha = 1;
785:     // loading door
786:     poly(ctx, [
787:       { x: g.L.x + 5, y: g.L.y - 12 }, { x: g.L.x + 16, y: g.L.y - 6 },
788:       { x: g.L.x + 16, y: g.L.y }, { x: g.L.x + 5, y: g.L.y + 6 }
789:     ], '#6f6455');
790:     // windows
791:     drawWindows(ctx, g.L, g.B, h, lv === 1 ? 1 : 2, 2, { top: 5, bottom: 7, winW: 3.8, winH: 4.4, color: '#b3dfe8' });
792:     if (lv >= 2) {
