794:       const s = iso(b.x + .78, b.y + .26);
795:       cylinder(ctx, s.x, s.y, 5.5, 18, '#c3cbc5');
796:       ellipse(ctx, s.x, s.y - 18, 5.5, 2.3, '#dbe2dc', '#9aa5a0', .8);
797:     }
