799:     const c = iso(b.x + .25, b.y + .3);
800:     cylinder(ctx, c.x, c.y - h, 3.2, lv === 3 ? 26 : 17, '#a7ada5');
801:     smoke(ctx, c.x, c.y - h - (lv === 3 ? 26 : 17), time, .8);
