804:     ctx.fillStyle = '#a87d4f'; ctx.fillRect(cr.x - 4, cr.y - 5, 5, 5); ctx.fillStyle = '#c69a62'; ctx.fillRect(cr.x + 1, cr.y - 3, 3, 3);
805:     if (lv === 3) {
