809:     for (let i = 0; i < 2; i++) { ctx.beginPath(); ctx.arc(iso(b.x + .35 + i * .1, b.y + .8).x, iso(b.x + .35 + i * .1, b.y + .8).y, 6, 0, 7); ctx.fill(); }
810:     ctx.globalAlpha = 1;
