886:       ], '#4d9ac4');
887:       line(ctx, { x: p.x - 8, y: p.y - lift + 3 }, { x: p.x + 6, y: p.y - lift + .6 }, 'rgba(255,255,255,.4)', .6);
888:       line(ctx, { x: p.x - 7, y: p.y - lift + 9 }, { x: p.x - 7, y: p.y + 2 }, '#7b837e', .9);
889:       line(ctx, { x: p.x + 6, y: p.y - lift + 7 }, { x: p.x + 6, y: p.y + 1 }, '#7b837e', .9);
890:     }
891:     ctx.globalAlpha = .5;
892:     for (let i = 0; i < 5; i++) {
893:       const p = iso(b.x + .2 + i * .5, b.y + 1.72);
894:       line(ctx, { x: p.x, y: p.y }, { x: p.x, y: p.y - 4 }, '#8b9683', 1);
