898:       for (const [gx, gy] of panels) {
899:         const p = iso(gx, gy);
900:         ctx.globalAlpha = .18; ctx.fillStyle = '#aee8ff'; ctx.beginPath(); ctx.arc(p.x, p.y - 14, 8, 0, 7); ctx.fill(); ctx.globalAlpha = 1;
901:       }
902:     }
