414:   // ---------- simulation ----------
415:   function levelVal(def, field, level) {
416:     const arr = def[field];
417:     if (Array.isArray(arr)) return arr[Math.min(level, arr.length - 1)] || 0;
418:     return arr || 0;
419:   }
420:   function zoneArtKind(def) {
421:     return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i';
422:   }
423:   function bCenter(b) { return { x: b.x + b.w / 2, y: b.y + b.h / 2 }; }
424:   function distance(a, b) {
425:     const ca = bCenter(a), cb = bCenter(b);
426:     return Math.hypot(ca.x - cb.x, ca.y - cb.y);
427:   }
428:   function nearbyArt(b, arts, radiusOverride) {
429:     for (const o of state.buildings) {
430:       if (o === b) continue;
431:       const d = defOf(o);
432:       if (!d) continue;
433:       const art = KK.render.artFor(d, o.level);
434:       if (!arts.includes(art)) continue;
435:       const r = radiusOverride || d.radius || 0;
436:       if (distance(b, o) <= r) return true;
437:     }
438:     return false;
439:   }
