565:   function simulateTick() {
566:     if (!state) return;
567:     state.tick++;
568:     const scale = periodScale();
569:     state.elapsedDays = (state.elapsedDays || 0) + PERIOD_DAYS[state.period];
570:     state.hour = (state.hour + .36 * scale) % 24;
571:     state.moodBoost *= Math.pow(.966, scale);
572:     if (Math.abs(state.moodBoost) < .05) state.moodBoost = 0;
573:     recalc();
574:     const hasPower = state.powerCap >= state.powerUse;
575:     const hasWater = state.waterCap >= state.waterUse;
576:     let changed = false;
577:     for (const b of state.buildings.slice()) {
578:       const d = defOf(b);
579:       if (!d || !d.kind || !d.kind.startsWith('zone')) continue;
580:       const ok = hasPower && hasWater && roadAccess(b);
581:       if (b.level === 0) {
582:         const kind = zoneArtKind(d);
583:         if (ok && demandFor(kind) > 0 && state.happiness >= 38) {
584:           b.growth += (1 + (state.happiness > 66 ? .5 : 0)) * scale;
585:           if (b.growth >= 2) { b.level = 1; b.growth = 0; b.evo = 0; changed = true; }
586:         } else b.growth = Math.max(0, b.growth - .5 * scale);
587:       } else {
588:         const school = nearbyArt(b, ['school']);
589:         const hospital = nearbyArt(b, ['hospital']);
590:         let maxLv = 3;
591:         if (kindOf(d) === 'r') maxLv = 2 + (school ? 1 : 0) + (hospital ? 1 : 0);
592:         if (b.level < Math.min(d.maxLevel || 3, maxLv) && ok && state.happiness >= 50) {
593:           b.evo += (state.happiness >= 68 ? 2 : 1) * scale;
594:           const need = [0, 7, 13, 21][b.level] || 99;
595:           if (b.evo >= need) { b.level++; b.evo = 0; changed = true; }
596:         } else if (b.evo > 0) b.evo = Math.max(0, b.evo - scale);
597:       }
598:     }
599:     if (changed) recalc();
600:     state.money += (state.income - state.expense) * scale;
601:     // resource warnings
602:     if (!state.warned.power && state.powerUse > state.powerCap && state.powerUse > 0) {
603:       toast('Listrik tidak cukup! Bangun pembangkit atau taman surya.', 'bad', 'bolt');
604:       state.warned.power = true;
605:     }
606:     if (state.powerUse <= state.powerCap) state.warned.power = false;
607:     if (!state.warned.water && state.waterUse > state.waterCap && state.waterUse > 0) {
608:       toast('Pasokan air kurang! Bangun menara air tambahan.', 'bad', 'drop');
609:       state.warned.water = true;
610:     }
611:     if (state.waterUse <= state.waterCap) state.warned.water = false;
612:     checkUnlocks();
613:     checkMissions();
614:     // random city event
615:     state.eventTimer = (state.eventTimer || 48) - scale;
616:     if (state.eventTimer <= 0) {
617:       state.eventTimer = 55 + Math.floor(Math.random() * 25);
618:       if (!state.modalPause && state.population >= 20) setTimeout(showRandomEvent, 350);
619:     }
620:     if (state.tick % Math.max(1, Math.round(2 / scale)) === 0) spawnCars();
621:     if (state.tick % Math.max(1, Math.round(20 / scale)) === 0) saveGame(true);
622:     updateAll();
623:     updateSelection();
624:   }
625:   function kindOf(def) { return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i'; }
626: 
627:   function checkUnlocks(silent) {
628:     if (!state) return;
629:     for (const id in DEFS) {
630:       const d = DEFS[id];
631:       if (!d.unlockPop || d.unlockPop > state.maxPop) continue;
632:       if (!state.unlocked[id]) {
633:         state.unlocked[id] = true;
634:         if (!silent) {
635:           toast(`Bangunan baru terbuka: ${d.name}`, 'reward', 'trophy');
636:           sfx.unlock();
637:         }
638:       }
639:     }
640:   }
641:   function checkMissions() {
642:     if (!state) return;
643:     for (const m of KK.MISSIONS) {
644:       if (state.missionsDone[m.id]) continue;
645:       if (m.check(state)) {
646:         state.missionsDone[m.id] = true;
647:         state.money += m.reward;
648:         sfx.reward();
649:         toast(`Misi selesai: ${m.label} · +${money(m.reward)}`, 'reward', 'trophy');
650:         if (m.id === 'metro' && !state.won) {
651:           state.won = true;
652:           setTimeout(showWin, 900);
653:         }
654:         updateHUD(true); renderMissions();
655:       }
656:     }
657:   }
